local keywordHandler = KeywordHandler:new()
local npcHandler = NpcHandler:new(keywordHandler)
NpcSystem.parseParameters(npcHandler)

function onCreatureAppear(cid)			npcHandler:onCreatureAppear(cid)			end
function onCreatureDisappear(cid)		npcHandler:onCreatureDisappear(cid)			end
function onCreatureSay(cid, type, msg)	npcHandler:onCreatureSay(cid, type, msg)	end
function onThink()						npcHandler:onThink()						end
npcHandler:setMessage(MESSAGE_GREET, 'What do you want, |PLAYERNAME|?')
npcHandler:setMessage(MESSAGE_FAREWELL, 'Leave now, |PLAYERNAME|. The gods of darkness will watch your soul!')
npcHandler:setMessage(MESSAGE_WALKAWAY, 'Leave now, |PLAYERNAME|. The gods of darkness will watch your soul!')
keywordHandler:addKeyword({'apocalypse'}, StdModule.say, {npcHandler = npcHandler, text = 'It is said even speaking its TRUE name will bring total destruction to you!'})
keywordHandler:addKeyword({'monster'}, StdModule.say, {npcHandler = npcHandler, text = 'They are a challenge to sift the chaff from the wheat.'})
keywordHandler:addKeyword({'suon'}, StdModule.say, {npcHandler = npcHandler, text = 'Suon is one of the suns of our world. He gives his light mindlessly to the weak and the strong alike.'})
keywordHandler:addKeyword({'slay'}, StdModule.say, {npcHandler = npcHandler, text = 'The weak have to be slain by the strong!'})
keywordHandler:addKeyword({'news'}, StdModule.say, {npcHandler = npcHandler, text = 'You will soon see the \'news\' with your own eyes. <chuckle>'})
keywordHandler:addKeyword({'fight'}, StdModule.say, {npcHandler = npcHandler, text = 'Life is an eternal fight!'})
keywordHandler:addKeyword({'goshnar'}, StdModule.say, {npcHandler = npcHandler, text = 'The necromant king was only defeated by the nightmare knights due to a bad twist of fate.'})
keywordHandler:addKeyword({'sell'}, StdModule.say, {npcHandler = npcHandler, text = 'I am in the death business. You wouldn\'t like what I have to offer.'})
keywordHandler:addKeyword({'air'}, StdModule.say, {npcHandler = npcHandler, text = 'Air is is just a mindless elemental force.'})
keywordHandler:addKeyword({'sula'}, StdModule.say, {npcHandler = npcHandler, text = 'Sula is just the mindless elemental power of water.'})
keywordHandler:addKeyword({'fardos'}, StdModule.say, {npcHandler = npcHandler, text = 'Fardos is the creator. He is a helpless watcher whose \'creation\' is far more then he bargained for.'})
keywordHandler:addKeyword({'archdemons'}, StdModule.say, {npcHandler = npcHandler, text = 'The demons are powerful followers of Zathroth. Their leaders are known as the ruthless seven.'})
keywordHandler:addKeyword({'help'}, StdModule.say, {npcHandler = npcHandler, text = 'If you cant help yourself you are not worth of my assistance.'})
keywordHandler:addKeyword({'urgith'}, StdModule.say, {npcHandler = npcHandler, text = 'Urgith is the master of the undead. The bonemaster also takes care of the damned souls.'})
keywordHandler:addKeyword({'tafariel'}, StdModule.say, {npcHandler = npcHandler, text = 'She is the mistress of the damned! Rewarding or torturing, it is the same for her victims!'})
keywordHandler:addKeyword({'excalibug'}, StdModule.say, {npcHandler = npcHandler, text = 'It\'s existence is just a lie to inspire hope and bravery in the hearts of the followers of good.'})
keywordHandler:addKeyword({'brog'}, StdModule.say, {npcHandler = npcHandler, text = 'Brog, the raging one, the great destroyer, the berserk of darkness ... call him how you like, but fear his awesome power.'})
keywordHandler:addKeyword({'zathroth'}, StdModule.say, {npcHandler = npcHandler, text = 'Zathroth represents the true and unbound power of magic. He is the keeper of great secrets.'})
keywordHandler:addKeyword({'fire'}, StdModule.say, {npcHandler = npcHandler, text = 'Fire is is just a mindless elemental force.'})
keywordHandler:addKeyword({'tibia'}, StdModule.say, {npcHandler = npcHandler, text = 'The world of Tibia is to be taken by the strongest.'})
keywordHandler:addKeyword({'ashfalor'}, StdModule.say, {npcHandler = npcHandler, text = 'The right hand of Urgith. The general of the undead hordes.'})
keywordHandler:addKeyword({'heal'}, StdModule.say, {npcHandler = npcHandler, text = 'Your wounds are your problem, not mine.'})
keywordHandler:addKeyword({'king'}, StdModule.say, {npcHandler = npcHandler, text = 'This puny king is no threat for our master\'s plans.'})
keywordHandler:addKeyword({'toth'}, StdModule.say, {npcHandler = npcHandler, text = 'Toth is just the undertaker for the other \'gods of good\'.'})
keywordHandler:addKeyword({'time'}, StdModule.say, {npcHandler = npcHandler, text = 'Who cares?'})
keywordHandler:addKeyword({'life'}, StdModule.say, {npcHandler = npcHandler, text = 'Life is war. It\'s about survival of the fittest.'})
keywordHandler:addKeyword({'bastesh'}, StdModule.say, {npcHandler = npcHandler, text = 'Bastesh is so afraid that she hides in the depth of the seas.'})
keywordHandler:addKeyword({'kirok'}, StdModule.say, {npcHandler = npcHandler, text = 'Kirok, the mad one, is the patron of scientists and jesters, more a nuisance than a god.'})
keywordHandler:addKeyword({'banor'}, StdModule.say, {npcHandler = npcHandler, text = 'Banor isn\'t a god at all, but one of their tools. It is stupidity to worship a tool, isn\'t it?'})
keywordHandler:addKeyword({'fafnar'}, StdModule.say, {npcHandler = npcHandler, text = 'Fafnar is the power of the sun. She burns the weak to ashes.'})
keywordHandler:addKeyword({'uman'}, StdModule.say, {npcHandler = npcHandler, text = 'Uman is a jealous keeper of magic. He gives only little knowledge to the mortals.'})
keywordHandler:addKeyword({'pumin'}, StdModule.say, {npcHandler = npcHandler, text = 'He is the lord of despair.'})
keywordHandler:addKeyword({'Verminor'}, StdModule.say, {npcHandler = npcHandler, text = 'Ah, the plaguelord.'})
keywordHandler:addKeyword({'citizen'}, StdModule.say, {npcHandler = npcHandler, text = 'The people of Tibia are sheep, so be smart and strong enough to become their wolf.'})
keywordHandler:addKeyword({'quest'}, StdModule.say, {npcHandler = npcHandler, text = 'Aren\'t we all on a quest for survival and supremacy?'})
keywordHandler:addKeyword({'nornur'}, StdModule.say, {npcHandler = npcHandler, text = 'Nornur fancies himself as god of fate without even understanding the ways of fate at all.'})
keywordHandler:addKeyword({'job'}, StdModule.say, {npcHandler = npcHandler, text = 'I am a priest of Zathroth, the bringer of dark secrets.'})
keywordHandler:addKeyword({'ferumbras'}, StdModule.say, {npcHandler = npcHandler, text = 'He is one of Zathroth\'s strongest followers and wields special powers, given to him by the dark one.'})
keywordHandler:addKeyword({'crunor'}, StdModule.say, {npcHandler = npcHandler, text = 'Crunor is a plantgod ... and plants exist to be stomped over.'})
keywordHandler:addKeyword({'name'}, StdModule.say, {npcHandler = npcHandler, text = 'My name is Lugri.'})
keywordHandler:addKeyword({'tibiasula'}, StdModule.say, {npcHandler = npcHandler, text = 'Zathroth took her life, recoginzig it was necessary for the process of creation.'})
keywordHandler:addKeyword({'bazir'}, StdModule.say, {npcHandler = npcHandler, text = 'He is the great deciver, the lord of lies.'})
keywordHandler:addKeyword({'infernatil'}, StdModule.say, {npcHandler = npcHandler, text = 'The incendiary of hell.'})

local shopModule = ShopModule:new()
npcHandler:addModule(shopModule)

local focusModule = FocusModule:new()
focusModule:addGreetMessage('hi')
focusModule:addGreetMessage('hello')
